function Message({
  message,
  pending,
  onApprovalDecision,
  approvalActions,
  diagnostics,
}: {
  message: ChatMessage;
  pending: boolean;
  onApprovalDecision?: (approval: AiApprovalPart, approved: boolean) => void;
  approvalActions?: Readonly<Record<string, AiApprovalActionState>>;
  diagnostics?: boolean;
}) {
  const { locale, l } = useLanguage(),
    { copy, copied } = useCopy();
  const user = message.role === "user";
  return (
    <div
      className={cn(
        "flex gap-3",
        user && "rounded-xl border border-border bg-surface p-4",
      )}
    >
      {user ? (
        <Avatar
          name="Alex Morgan"
          src={demoAvatarSources["alex-morgan"]}
          className="size-7 text-[10px]"
        />
      ) : (
        <span className="flex size-8 shrink-0 items-center justify-center rounded-lg bg-accent">
          <AureformMark className="size-5 text-primary" />
        </span>
      )}
      <div className="min-w-0 flex-1">
        <p className="mb-2 text-xs font-semibold">
          {user ? l("You", "Tú") : "Aureform"}
        </p>
        <AiMessageParts message={message} locale={locale}
          onApprovalDecision={onApprovalDecision} approvalActions={approvalActions} diagnostics={diagnostics} />
        {!user && message.content && !pending && (
          <Button
            variant="ghost"
            size="icon-sm"
            className="mt-2"
            aria-label={l("Copy response", "Copiar respuesta")}
            onClick={() => {
              void copy(message.content);
            }}
          >
            {copied ? <Check /> : <Copy />}
          </Button>
        )}
      </div>
    </div>
  );
}

import * as React from "react";
import { Info, CircleCheck, TriangleAlert } from "lucide-react";
import { cn } from "@/lib/utils";
export function Alert({
  title,
  children,
  variant = "info",
  className,
}: {
  title: string;
  children?: React.ReactNode;
  variant?: "info" | "success" | "warning" | "destructive";
  className?: string;
}) {
  const Icon =
    variant === "success"
      ? CircleCheck
      : variant === "warning" || variant === "destructive"
        ? TriangleAlert
        : Info;
  return (
    <div
      role={variant === "destructive" ? "alert" : "status"}
      className={cn(
        "flex gap-3 rounded-lg border p-4 text-xs",
        variant === "warning"
          ? "border-warning-foreground/20 bg-warning text-warning-foreground"
          : variant === "destructive"
            ? "border-destructive-foreground/20 bg-destructive text-destructive-foreground"
            : "border-primary/15 bg-accent text-accent-foreground",
        className,
      )}
    >
      <Icon className="mt-0.5 size-4 shrink-0" />
      <div>
        <p className="font-semibold">{title}</p>
        {children && <div className="mt-1 leading-relaxed">{children}</div>}
      </div>
    </div>
  );
}

